// Shared scientific UI. No topic, data-bundle or page imports.
import {publicText} from './public-text.js';
export const confidenceLabels = {high:['HIGH','Висока впевненість'],moderate:['MODERATE','Помірна впевненість'],low:['LOW','Низька впевненість'],very_low:['VERY LOW','Дуже низька впевненість'],insufficient:['INSUFFICIENT','Недостатньо даних']};
export const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=value=>escapeHTML(publicText(value));
const date=value=>new Intl.DateTimeFormat('uk-UA',{dateStyle:'long',timeZone:'UTC'}).format(new Date(value+'T00:00:00Z'));
const types={performance:'Продуктивність',efficacy:'Ефект',safety:'Безпека',physiology:'Фізіологія',mechanism:'Механізм',harm:'Шкода',association:'Асоціація',nutrition:'Харчування'};
const layers={human_outcome:'Результати у людей',mechanistic:'Механістичні дані',mixed:'Результати у людей + механізм'};
const publicationTypes={systematic_review_meta_analysis:'Систематичний огляд і метааналіз',meta_analysis:'Метааналіз',systematic_review:'Систематичний огляд',original_research:'Оригінальне дослідження',position_statement:'Позиційний документ',guideline:'Настанова',narrative_review:'Огляд механізмів',textbook_chapter:'Розділ підручника',other:'Інше'};
export function getClaim(id,base){const claim=base.claims.find(c=>c.id===id);if(!claim)throw new Error('Unknown Claim: '+id);return claim;}
export function ReviewDetails(id,base){const assessments=(base.assessments||[]).filter(a=>a.claimId===id);if(!assessments.length)return '';const labels={risk_of_bias:'Ризик упередженості',inconsistency:'Неузгодженість',indirectness:'Непрямість',imprecision:'Неточність',publication_bias:'Публікаційне упередження'};return `<details class="eua-review-record"><summary>Оцінка впевненості та історія перевірки</summary>${assessments.map(a=>{const review=(base.reviews||[]).find(r=>r.assessmentId===a.id);return `<p>${e(a.id)} · Версія твердження ${e(a.claimVersion)} · ${a.status==='draft'?'Чернетка оцінки':e(a.status)}</p><p>${e(a.rationale)}</p><p>Використані записи доказів: ${e(a.evidenceRecordIds.join(', '))}</p><ul>${Object.entries(a.domains).map(([key,d])=>`<li><b>${e(labels[key]||key)}:</b> ${d.status==='not_assessed'?'ще не оцінено':e(d.status)}. ${e(d.rationale)}</li>`).join('')}</ul><p>Наукове схвалення: ${review?.status==='approved'?'Зафіксоване':'не виконане'}</p>${(review?.history||[]).map(h=>`<p>${date(h.at)} · ${e(h.note)}</p>`).join('')}`;}).join('')}</details>`;}
export function recordsFor(id,base){return base.records.filter(r=>r.claimId===id);}
const list=items=>`<ul>${items.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`;
const link=(url,label)=>`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(label)} ↗</a>`;
export function ConfidenceBadge(claim){if(claim.evidenceConfidence===null)return '<span class="eua-provisional" data-confidence="not-assessed">Рівень впевненості не оцінено</span>';const [code,label]=confidenceLabels[claim.evidenceConfidence];return `<span class="eua-confidence eua-${claim.evidenceConfidence}" data-confidence="${e(claim.evidenceConfidence)}"><b>${code}</b> — ${label}</span>${claim.provisional?'<span class="eua-provisional">Попередня оцінка · науковий перегляд триває</span>':''}`;}
export function ScientificNote(text){return `<aside class="eua-note"><span>Наукове уточнення</span><p>${e(text)}</p></aside>`;}
export function EvidenceGap(text='Наразі недостатньо даних для надійного висновку.'){return `<aside class="eua-gap"><b>Межа знання</b><p>${e(text)}</p></aside>`;}
export function claimButton(id,label='Чому ми так стверджуємо?'){return `<button type="button" class="eua-evidence-button" data-claim-open="${e(id)}" aria-haspopup="dialog">${e(label)} <span aria-hidden="true">↗</span></button>`;}
export function ClaimCard(id,base){const c=getClaim(id,base);return `<article class="eua-claim" data-claim-id="${e(c.id)}"><div class="eua-kicker">${e(types[c.claimType]||c.claimType)} · ${e(layers[c.evidenceLayer])}</div><h3>${e(base.presentation?.labels?.[id]||c.outcome.name)}</h3><p class="eua-statement">${e(c.shortStatement)}</p>${ConfidenceBadge(c)}<p>${e(c.evidenceSummary)}</p><div class="eua-context"><span>Для кого / контекст</span><p>${e(c.population.description)}</p></div><div class="eua-context"><span>Ключове обмеження</span><p>${e(c.limitations[0]||'Оцінку обмежень ще не завершено.')}</p></div>${c.evidenceConfidence==='insufficient'?EvidenceGap():''}${claimButton(id)}</article>`;}
function effect(r){if(!r.result)return 'Числова оцінка не внесена.';const v=r.result;if(v.estimate===undefined||v.estimate===null)return e(v.summary||v.description||'Числова оцінка не внесена.');const n=x=>new Intl.NumberFormat('uk-UA',{maximumFractionDigits:3}).format(x);return `${e(v.effectMeasure||'Оцінка')}: <b>${n(v.estimate)} ${e(v.unit||'')}</b>${v.lowerCI!==undefined&&v.upperCI!==undefined?` · ${e(v.confidenceLevel||95)}% ДІ ${n(v.lowerCI)}–${n(v.upperCI)}`:' · ДІ: див. першоджерело'}`;}
function sourceDisclosures(source){
 const reported=value=>value?.status==='reported'&&typeof value.summary==='string'&&value.summary.trim();
 if(!reported(source.funding)&&!reported(source.conflicts))return '<p>Фінансування й конфлікти інтересів: ще не перевірено за повним текстом</p>';
 return `<p>Фінансування: ${reported(source.funding)?e(source.funding.summary):'ще не перевірено за повним текстом'}</p><p>Конфлікти інтересів: ${reported(source.conflicts)?e(source.conflicts.summary):'ще не перевірено за повним текстом'}</p>`;
}
export function SourceCard(source,records=[],advanced=true,idPrefix='source',headingLevel=4){const heading=headingLevel===3?'h3':'h4';return `<article class="eua-source" id="${e(idPrefix)}-${e(source.id)}"><div class="eua-kicker">${e(source.year)} · ${e(publicationTypes[source.publicationType]||source.publicationType)}</div><${heading}>${e(source.title)}</${heading}><p>${e(source.shortCitation)}</p><dl><dt>Що оцінювали</dt><dd>${e(source.populationSummary||source.methodsSummary||'Контекст потрібно уточнити.')}</dd><dt>Основний результат для цих тверджень</dt><dd>${records.length?records.map(r=>`<p>${e(r.outcome.name)} — ${effect(r)}</p>`).join(''):e(source.methodsSummary||'Джерело практичного guidance / механізму; не outcome-доказ для всіх Claims.')}</dd><dt>Основне обмеження</dt><dd>${e(source.keyLimitations?.[0]||'Повний аудит обмежень ще не завершено.')}</dd></dl>${source.sourceStatus==='not_checked'?'<p class="eua-provisional">Статус публікації ще не перевірено.</p>':source.sourceStatus!=='active'?`<p class="eua-gap">Статус публікації: ${e(source.sourceStatus)}. Потрібен перегляд пов’язаних Claims.</p>`:''}<div class="eua-source-links">${source.pubmedUrl?link(source.pubmedUrl,'PubMed · PMID '+source.identifiers.pmid):''}${source.identifiers.doi?link('https://doi.org/'+source.identifiers.doi,'DOI'):''}${source.url&&source.url!==source.pubmedUrl?link(source.url,source.pubmedUrl?'Текст / запис джерела':'Відкрити джерело'):''}${source.fullTextUrl&&source.fullTextUrl!==source.url?link(source.fullTextUrl,source.fullTextAccess==='preview_only'?'Перегляд джерела':'Текст публікації'):''}</div>${advanced?`<details><summary>Методи, фінансування та обмеження</summary><p>${e(source.methodsSummary||'Методи не внесено.')}</p>${list(source.keyLimitations||[])}${source.accessNote?`<p>${e(source.accessNote)}</p>`:''}${sourceDisclosures(source)}<details><summary>Технічна довідка</summary><p>Перевірка метаданих: ${date(source.lastChecked)} · ${e(source.id)}</p></details></details>`:''}</article>`;}
function OutcomeEvidenceDrawer(id,base){const c=getClaim(id,base),records=recordsFor(id,base);const sources=[...new Set(records.map(r=>r.sourceId))].map(id=>base.sources.find(s=>s.id===id)).filter(Boolean);const conflicting=records.filter(r=>r.direction==='conflicts_with_claim'||r.direction==='mixed');return `<div class="eua-drawer-head"><div class="eua-kicker">${e(c.id)} · ${e(types[c.claimType]||c.claimType)}</div><button type="button" data-evidence-close aria-label="Закрити докази">✕</button></div><h2 id="eua-drawer-title">${e(c.statement)}</h2>${ConfidenceBadge(c)}<p>${e(layers[c.evidenceLayer])}</p><h3>Що показує сукупність даних</h3><p>${e(c.evidenceSummary)}</p>${c.practicalMeaning?`<p class="eua-practical">${e(c.practicalMeaning)}</p>`:''}<h3>Ефект і конкретні результати</h3>${records.map(r=>`<div class="eua-record"><b>${e(r.outcome.name)}</b><p>${effect(r)}</p><small>${e(r.id)} → ${e(r.sourceId)} · витяг: ${r.reviewStatus==='pending'?'потребує наукової перевірки':e(r.reviewStatus)}</small></div>`).join('')||EvidenceGap()}<h3>Популяція й порівняння</h3><p>${e(c.population.description)}</p><p>${e(c.population.notes||'')}</p><p><b>Втручання:</b> ${e(c.intervention?.name||'Не застосовується')} ${e(c.intervention?.dose||'')}</p><p><b>Порівняння:</b> ${e(c.comparator?.description||'Не внесено')}</p><h3>Чому така впевненість?</h3><p>${e(c.confidenceRationale.summary)}</p>${list(c.confidenceRationale.uncertaintyNotes||[])}${list(c.confidenceRationale.downgradeDomains||[])}${ScientificNote(base.presentation?.confidenceNote||'Впевненість належить конкретному outcome. Попередня оцінка не є завершеним формальним GRADE assessment.')}${ReviewDetails(id,base)}<h3>Обмеження</h3>${list(c.limitations)}${c.applicability?.doNotExtrapolateTo?.length?`<p><b>Не переносити автоматично на:</b> ${e(c.applicability.doNotExtrapolateTo.join(', '))}</p>`:''}<h3>Неузгоджені дані</h3>${conflicting.length?conflicting.map(r=>`<p>${e(r.outcome.name)}: ${e(r.interpretation||r.result?.summary||r.direction)}</p>`).join(''):'<p>У поточній базі даних окремі суперечливі записи не внесені. Це не доказ відсутності суперечливих досліджень.</p>'}<details><summary>Рівень 3 · Записи доказів та методологія</summary><p>Ризик упередженості, неузгодженість, непрямість, неточність та публікаційне упередження оцінюються для конкретного outcome. Повний аудит конкретних результатів ще не завершено; наявність метааналізу не присвоює HIGH автоматично.</p>${records.map(r=>`<div class="eua-record"><b>${e(r.id)}</b><p>Напрям: ${e(r.direction)} · Роль: ${e(r.roleForClaim)} · Відповідність: ${e(r.relevance)} · ${e(layers[r.evidenceLayer])}</p><p>${e(r.interpretation||'')}</p>${list(r.extractionNotes||[])}<p>Ризик упередженості: ${e(r.riskOfBias?.summary||'не завершено')}</p>${r.result?.heterogeneityI2!==undefined?`<p>I²: ${e(r.result.heterogeneityI2)}% — не автоматична причина зниження впевненості.</p>`:''}</div>`).join('')}</details><h3>Джерела саме цього твердження</h3>${sources.map(s=>SourceCard(s,records.filter(r=>r.sourceId===s.id),true,'drawer-'+id)).join('')}<footer class="eua-reviewed"><p>Дата попереднього огляду: ${c.lastReviewed?date(c.lastReviewed):'не завершено'}</p><p>Версія доказів: ${e(c.version)} · ${e(c.status)}${c.nextReview?` · наступний огляд: ${date(c.nextReview)}`:''}</p></footer>`;}


export { date, list, link };
export function bindEvidenceUI(base){return {confidenceLabels,escapeHTML,ConfidenceBadge,ScientificNote,EvidenceGap,claimButton,SourceCard,getClaim:(id,selected=base)=>getClaim(id,selected),recordsFor:(id,selected=base)=>recordsFor(id,selected),ClaimCard:(id,selected=base)=>ClaimCard(id,selected),EvidenceDrawer:(id,selected=base)=>EvidenceDrawer(id,selected),ReviewDetails:(id,selected=base)=>ReviewDetails(id,selected)};}
export function mountEvidenceDrawer(root,base,{dialogSelector='#eua-evidence-dialog'}={}){
 if(!root)return;const dialog=root.querySelector(dialogSelector);if(!dialog)throw Error('Evidence dialog missing');let returnFocus=null;
 const close=()=>{dialog.close();returnFocus?.focus();};
 const onRoot=event=>{const opener=event.target.closest('[data-claim-open]');if(opener){returnFocus=opener;dialog.querySelector('[data-evidence-content]').innerHTML=EvidenceDrawer(opener.dataset.claimOpen,base);dialog.showModal();dialog.scrollTop=0;dialog.querySelector('[data-evidence-close]').focus();}if(event.target.closest('[data-evidence-close]'))close();};
 const onBackdrop=event=>{if(event.target===dialog){const b=dialog.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)close();}};
 const onClose=()=>returnFocus?.focus();
 root.addEventListener('click',onRoot);dialog.addEventListener('click',onBackdrop);dialog.addEventListener('close',onClose);
 return ()=>{root.removeEventListener('click',onRoot);dialog.removeEventListener('click',onBackdrop);dialog.removeEventListener('close',onClose);};
}

// Mechanistic descriptions have provenance, not an invented outcome effect or GRADE score.
export function EvidenceDrawer(id,base){
 const c=getClaim(id,base);
 if(c.evidenceLayer!=='mechanistic')return OutcomeEvidenceDrawer(id,base);
 const records=recordsFor(id,base),sources=[...new Set(records.map(r=>r.sourceId))].map(id=>base.sources.find(s=>s.id===id)).filter(Boolean);
 return `<div class="eua-drawer-head"><div class="eua-kicker">${base.presentation?.showClaimType?e(types[c.claimType]||c.claimType):'Фізіологія · механізм'}</div><button type="button" data-evidence-close aria-label="Закрити пояснення">✕</button></div><h2 id="eua-drawer-title">${e(c.statement)}</h2>${ConfidenceBadge(c)}${base.presentation?.showContextExplanation&&records.length&&records.every(r=>r.roleForClaim==='context_only')?`<h3>Збережене навчальне пояснення</h3><p>${e(c.evidenceSummary)}</p>`:''}<h3>Чому ми так пояснюємо</h3>${records.map(r=>`<div class="eua-record">${base.presentation?.showSourceLocators&&r.claimPartLabel?`<b>${e(r.claimPartLabel)}</b>`:''}<p>${e(r.result.summary||r.result.description)}</p><p>${e(r.populationContext.description)}</p>${base.presentation?.showSourceLocators?`<p><b>Де в джерелі:</b> ${escapeHTML(r.extractionLocator)}</p>`:''}${r.roleForClaim==='context_only'?'<small>Лише контекст: цей запис не підтверджує всі частини твердження.</small>':''}</div>`).join('')}<h3>Межі пояснення</h3>${list(c.limitations)}${ScientificNote(base.presentation?.confidenceNote||'Механізм не є оцінкою клінічного або спортивного результату.')}<h3>Джерела саме цього твердження</h3>${sources.map(s=>SourceCard(s,records.filter(r=>r.sourceId===s.id),true,'drawer-'+id)).join('')}<details><summary>Технічна довідка</summary><p>Твердження: ${e(c.id)} · версія ${e(c.version)}</p>${records.map(r=>`<p>${e(r.id)} → ${e(r.sourceId)} · ${escapeHTML(r.extractionLocator)}</p>`).join('')}</details><footer class="eua-reviewed"><p>Науковий перегляд: ${c.lastReviewed?date(c.lastReviewed):'не завершено'}</p><p>Версія навчального матеріалу: ${e(c.version)}</p><p>${e(c.confidenceRationale.summary)}</p></footer>`;
}
